<?php
require_once 'auth.php'; require_once 'auth_ui.php'; if(!empty($_SESSION['auth_user'])){header('Location: index.php');exit;}
$error=''; $name='';$email=''; if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';
 if(mb_strlen($name)<2||mb_strlen($name)>100)$error='Enter your full name (2–100 characters).';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.';elseif(strlen($pass)<10||!preg_match('/[A-Za-z]/',$pass)||!preg_match('/[0-9]/',$pass))$error='Use at least 10 characters, including at least one letter and one number.';elseif($pass!==$confirm)$error='The passwords do not match.';else{try{$db=auth_db();$s=$db->prepare('INSERT INTO auth_users(full_name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['flash']=['type'=>'success','message'=>'Account created. Sign in with your new credentials.'];header('Location: login.php');exit;}catch(PDOException $e){$error=$e->getCode()==='23000'?'An account with that email already exists.':'Unable to create your account. Confirm auth_setup.sql has been imported.';}catch(Throwable $e){$error='Unable to create your account. Confirm auth_setup.sql has been imported.';}}}
auth_page_start('Create your account','Set up your secure LabAsset workspace access.');if($error)echo '<div class="auth-alert error">'.h($error).'</div>'; ?>
<form method="post" class="auth-form"><label for="full_name">Full name</label><input id="full_name" name="full_name" autocomplete="name" placeholder="Your full name" required maxlength="100" value="<?= h($name) ?>"><label for="email">Work email</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@organization.edu" required value="<?= h($email) ?>"><label for="password">Create password</label><input id="password" name="password" type="password" autocomplete="new-password" minlength="10" placeholder="At least 10 characters" required><p class="field-hint">Use 10+ characters with at least one letter and one number.</p><label for="confirm_password">Confirm password</label><input id="confirm_password" name="confirm_password" type="password" autocomplete="new-password" placeholder="Re-enter password" required><button class="auth-submit" type="submit">Create account <span>→</span></button></form><p class="auth-switch">Already registered? <a href="login.php">Sign in</a></p><p class="auth-note">New accounts receive the Staff role. Administrator permissions must be assigned by an authorized database administrator.</p><?php auth_page_end(); ?>